+    `LF:${file.lines.length}`, `LH:${hit(file.lines)}`,
+    ...file.branches.map((branch, index) => `BRDA:${branch.line},${index},0,${branch.count}`),
+    `BRF:${file.branches.length}`, `BRH:${hit(file.branches)}`, 'end_of_record', ''].join('\n')).join('');
